fn format_number(n: usize, fmt: &Option<String>) -> String {
    match fmt.as_deref() {
        Some("commas") => {
            let s = n.to_string();
            let mut res = String::new();
            let mut count = 0;
            for c in s.chars().rev() {
                if count==3 { res.push(','); count=0; }
                res.push(c);
                count+=1;
            }
            res.chars().rev().collect()
        },
        Some("dots") => {
            let s = n.to_string();
            let mut res = String::new();
            let mut count = 0;
            for c in s.chars().rev() {
                if count==3 { res.push('.'); count=0; }
                res.push(c);
                count+=1;
            }
            res.chars().rev().collect()
        },
        Some("underscores") => {
            let s = n.to_string();
            let mut res = String::new();
            let mut count = 0;
            for c in s.chars().rev() {
                if count==3 { res.push('_'); count=0; }
                res.push(c);
                count+=1;
            }
            res.chars().rev().collect()
        },
        _ => n.to_string(),
    }
}

fn count_lines_for_language(path: &Path, lang_name: &str) -> CodeStats {
    // Very simplified counting: blanks = lines that are empty or whitespace only
    // comments = lines where trimmed starts with comment marker
    // code = remainder
    // Need language-specific markers
    let content = match std::fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return CodeStats::new(),
    };
    // For binary files, maybe inaccurate? Ignore
    let is_markdown = lang_name == "Markdown";
    if is_markdown {
        return count_markdown(&content);
    }
    // Determine comment markers
    let (line_comment, block_start, block_end) = comment_markers(lang_name);
    let mut stats = CodeStats::new();
    let mut in_block = false;
    let mut in_block_depth = 0; // for nested? Not needed
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            stats.blanks += 1;
            continue;
        }
        if in_block {
            stats.comments += 1;
            if let Some(end) = block_end {
                if trimmed.contains(end) {
                    // simple: if line contains block_end, exit block
                    // handle nested? ignore
                    in_block = false;
                }
            }
            continue;
        }
        // check block start
        if let Some(start) = block_start {
            if trimmed.starts_with(start) || trimmed.contains(start) {
                // if line is purely block comment start?
                // For simplicity, if line contains block start, treat as comment
                // Also handle inline block comment?
                // If line contains both start and end on same line, it's comment? But tokei might count as code if code before?
                // Simplify: if line contains block start, count as comment unless code before?
                // We'll approximate: if trimmed.starts_with(start) => comment
                if trimmed.starts_with(start) {
                    stats.comments += 1;
                    if let Some(end) = block_end {
                        if !trimmed.contains(end) || trimmed.find(start).unwrap() < trimmed.find(end).unwrap() && trimmed.matches(start).count() != trimmed.matches(end).count() {
                            in_block = true;
                        }
                    } else {
                        in_block = true;
                    }
                    continue;
                }
            }
        }
        if let Some(lc) = line_comment {
            if trimmed.starts_with(lc) {
                stats.comments += 1;
                continue;
            }
            // Also treat inline comment after code? Original tokei would count line as code if code before comment, not as comment.
            // Example hello.rs: println!("hello"); is code not comment, even though not containing comment.
            // For line like `x = 1 # comment` in python, tokei counts as code, not comment (maybe?).
            // So we should not count inline comments as comment lines, they're code.
            // So only lines that are purely comment counted as comments? Actually tokei's definition: comments are lines containing only comments? Let's check.
            // In earlier test: hello.py with `print("hello") # inline comment?` wasn't in file, but test with hello.py had 5 lines: 1 comment, 3 code, 1 blank. That file: "# comment\ndef foo():\n    print(\"hello\") # inline comment?\n    pass\n\n" => Which lines? 1 "# comment" => comment, 2 "def foo():" => code, 3 "    print(...)" with inline comment => likely counted as code not comment, 4 "    pass" => code, 5 blank => blank => So 1 comment, 3 code, 1 blank. So inline comment not counted as comment.
            // Similarly for our counting, we count inline as code.
        }
        stats.code += 1;
    }
    // For Markdown, already handled
    stats
}

fn comment_markers(lang: &str) -> (Option<&'static str>, Option<&'static str>, Option<&'static str>) {
    match lang {
        "Rust" | "C" | "C++" | "C Header" | "C++ Header" | "Java" | "JavaScript" | "TypeScript" | "TSX" | "Go" | "Swift" | "Kotlin" | "Scala" | "C#" | "PHP" => (Some("//"), Some("/*"), Some("*/")),
        "Python" | "Ruby" | "Shell" | "BASH" | "Batch" | "Perl" | "R" | "Makefile" | "Dockerfile" | "YAML" | "TOML" => (Some("#"), None, None),
        "Markdown" => (None, None, None),
        "HTML" | "XML" => (None, Some("<!--"), Some("-->")),
        "CSS" => (None, Some("/*"), Some("*/")),
        "Plain Text" => (None, None, None),
        _ => (Some("//"), None, None), // default
    }
}

fn count_markdown(content: &str) -> CodeStats {
    // Markdown: treat lines outside code blocks as comments, blanks as blanks, code is 0.
    // Code blocks are fenced with ``` and language after.
    // For each code block, we need to count its interior as code in blob for that language.
    // The markdown file's stats: blanks = blank lines outside code blocks, comments = non-blank lines outside blocks, code = 0, blobs = map of language -> stats for code inside.
    // We need to parse fenced blocks.
    let mut stats = CodeStats::new();
    let mut in_code = false;
    let mut code_lang: Option<String> = None;
    let mut code_lines: Vec<String> = Vec::new();
    let mut blobs: BTreeMap<String, CodeStats> = BTreeMap::new();

    for line in content.lines() {
        let trimmed = line.trim();
        if !in_code && trimmed.starts_with("```") {
            // start code block
            in_code = true;
            let lang = trimmed.trim_start_matches("```").trim().to_string();
            // if lang empty, default to maybe Plain Text? But treat as unknown -> ignore?
            code_lang = if lang.is_empty() { None } else { Some(lang) };
            code_lines.clear();
            continue;
        } else if in_code && trimmed.starts_with("```") {
            // end block
            in_code = false;
            if let Some(lang) = code_lang.take() {
                // need to map lang string to canonical language name (e.g., "rust" -> "Rust", "python" -> "Python")
                let canonical = canonical_language(&lang);
                if let Some(canonical) = canonical {
                    // Count lines inside block for that language
                    let mut blk = CodeStats::new();
                    for cl in &code_lines {
                        let t = cl.trim();
                        if t.is_empty() {
                            blk.blanks += 1;
                        } else {
                            // For simplicity, treat all non-blank inside code block as code (even if comments?) But tokei would parse those as code/comments according to language.
                            // For accuracy, we should call count_lines_for_language for that lang on temporary? But we have lines, we can count via markers for that lang.
                            // Let's count via same logic for that language but using the snippet content
                            // For now simple: if line is comment for that lang, count as comments else code.
                            let (lc, bs, be) = comment_markers(canonical);
                            if let Some(lc) = lc {
                                if t.starts_with(lc) {
                                    blk.comments += 1;
                                    continue;
                                }
                            }
                            // ignore block handling for code snippet
                            blk.code += 1;
                        }
                    }
                    // Merge into blobs (aggregate per language)
                    blobs.entry(canonical.to_string()).and_modify(|e| {
                        e.blanks += blk.blanks;
                        e.code += blk.code;
                        e.comments += blk.comments;
                    }).or_insert(blk);
                } else {
                    // unknown language inside markdown, maybe count as code for markdown's blob? But tokei would treat unknown as maybe not counting? We'll ignore.
                }
            }
            continue;
        }
        if in_code {
            code_lines.push(line.to_string());
        } else {
            if trimmed.is_empty() {
                stats.blanks += 1;
            } else {
                stats.comments += 1;
            }
        }
    }
    // If still in code at EOF, handle similarly
    if in_code {
        if let Some(lang) = code_lang {
            let canonical = canonical_language(&lang);
            if let Some(canonical) = canonical {
                let mut blk = CodeStats::new();
                for cl in &code_lines {
                    let t = cl.trim();
                    if t.is_empty() { blk.blanks+=1; }
                    else {
                        let (lc,_,_) = comment_markers(canonical);
                        if let Some(lc)=lc { if t.starts_with(lc) {blk.comments+=1; continue;} }
                        blk.code+=1;
                    }
                }
                blobs.entry(canonical.to_string()).and_modify(|e|{
                    e.blanks+=blk.blanks; e.code+=blk.code; e.comments+=blk.comments;
                }).or_insert(blk);
            }
        }
    }
    stats.blobs = blobs;
    stats
}

fn canonical_language(s: &str) -> Option<&'static str> {
    let lower = s.to_ascii_lowercase();
    match lower.as_str() {
        "rust" | "rs" => Some("Rust"),
        "python" | "py" => Some("Python"),
        "javascript" | "js" => Some("JavaScript"),
        "typescript" | "ts" => Some("TypeScript"),
        "c" => Some("C"),
        "c++" | "cpp" | "cxx" => Some("C++"),
        "go" => Some("Go"),
        "java" => Some("Java"),
        "ruby" | "rb" => Some("Ruby"),
        "shell" | "sh" | "bash" => Some("Shell"),
        "json" => Some("JSON"),
        "toml" => Some("TOML"),
        "yaml" | "yml" => Some("YAML"),
        "html" => Some("HTML"),
        "css" => Some("CSS"),
        "markdown" | "md" => Some("Markdown"),
        "dockerfile" => Some("Dockerfile"),
        "makefile" => Some("Makefile"),
        "plain text" | "txt" | "text" => Some("Plain Text"),
        _ => {
            // Try to match our language list case-insensitively
            for def in language_definitions() {
                if def.name.to_ascii_lowercase() == lower {
                    return Some(def.name);
                }
            }
            None
        }
    }
}

fn detect_language(path: &Path) -> Option<String> {
    let filename = path.file_name()?.to_string_lossy().to_string();
    let ext = path.extension().and_then(|e| e.to_string_lossy().into_owned().into()).or(None);
    // Check filenames first (case sensitive? treat case insensitive for Dockerfile etc)
    for def in language_definitions() {
        for fname in &def.filenames {
            if filename == *fname {
                return Some(def.name.to_string());
            }
            // also handle lower case for makefile etc
            if filename.eq_ignore_ascii_case(fname) {
                return Some(def.name.to_string());
            }
        }
    }
    // Also check special filenames like Dockerfile, Makefile, CMakeLists.txt handled above, but also for file without extension like Makefile case we already handled
    // For extensions
    if let Some(ext_str) = ext {
        let ext_lower = ext_str.to_ascii_lowercase();
        for def in language_definitions() {
            for e in &def.extensions {
                if e.eq_ignore_ascii_case(&ext_lower) {
                    return Some(def.name.to_string());
                }
            }
        }
        // Also handle some plain mapping for common: "rs" etc already, but ensure
        // For files like ".rs" hidden maybe still
    } else {
        // No extension, could be like "Dockerfile" already handled, or "Makefile"
        // Check for known names like "Rakefile", "Gemfile" etc via filename exact
        // For now ignore
    }
    // Fallbacks for text?
    if filename.to_ascii_lowercase().ends_with(".txt") {
        return Some("Plain Text".to_string());
    }
    None
}

fn detect_language_from_path_str(s: &str) -> Option<String> {
    detect_language(Path::new(s))
}

