fn should_exclude(path: &Path, exclude_patterns: &[globset::Glob]) -> bool {
    // Use file_name matching or full path?
    // Tokei's exclude semantics same as gitignore: pattern matching relative to root? For simplicity, match file_name and full path string
    let path_str = path.to_string_lossy();
    let file_name = path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
    for pat in exclude_patterns {
        let matcher = pat.compile_matcher();
        // try match file_name and path_str
        if matcher.is_match(&file_name) || matcher.is_match(path.as_os_str().to_string_lossy().as_ref()) || matcher.is_match(path_str.as_ref()) {
            return true;
        }
        // Also match with glob crate? For patterns like "*.rs", glob crate matches path component?
        // Use glob::Pattern for each pattern string alternative
    }
    // Use glob::Pattern matching for exclude patterns as original did via gitignore semantics: we can use globset with additional handling?
    // Instead, also use glob::Pattern match on file_name and relative path
    for pat_str in exclude_patterns.iter().map(|g| g.glob().glob().to_string()) {
        if let Ok(glob_pat) = glob::Pattern::new(&pat_str) {
            if glob_pat.matches(&file_name) || glob_pat.matches(&path_str) {
                return true;
            }
            // also match any path component
            for comp in path.components() {
                if let Some(s) = comp.as_os_str().to_str() {
                    if glob_pat.matches(s) {
                        return true;
                    }
                }
            }
        }
    }
    false
}

