fn main() {
    let cmd = build_cli();
    let mut args: Vec<String> = std::env::args().collect();
    // Handle --help and --version manually due to disabled flags
    let has_help = args.iter().any(|a| a=="--help" || a=="-h");
    let has_version = args.iter().any(|a| a=="--version" || a=="-V");
    if has_help {
        print_help();
        return;
    }
    if has_version && !has_help {
        println!("tokei 14.0.0 compiled with serialization support: json");
        return;
    }
    let matches = match cmd.try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            e.exit();
        }
    };

    if matches.get_flag("help") {
        print_help();
        return;
    }
    if matches.get_flag("version") {
        println!("tokei 14.0.0 compiled with serialization support: json");
        return;
    }

    if matches.get_flag("languages") {
        print!("{}", LANGUAGES_TABLE);
        return;
    }

    // Validate output
    if let Some(out) = matches.get_one::<String>("output") {
        let lower = out.to_ascii_lowercase();
        let allowed = ["json"];
        if !allowed.contains(&lower.as_str()) {
            if ["yaml","yml","cbor"].contains(&lower.as_str()) {
                eprintln!("error: invalid value '{}' for '--output <output>': This version of tokei was compiled without any '{}' serialization support, to enable serialization, reinstall tokei with the features flag.", out, lower);
                eprintln!("\n    cargo install tokei --features {}", lower);
                eprintln!("\nIf you want to enable all supported serialization formats, you can use the 'all' feature.");
                eprintln!("\n    cargo install tokei --features all\n\n\nFor more information, try '--help'.");
                std::process::exit(2);
            } else {
                eprintln!("error: invalid value '{}' for '--output <output>': \"{}\" is not a supported serialization format", out, out);
                eprintln!("\nFor more information, try '--help'.");
                std::process::exit(2);
            }
        }
    }

    let verbose = matches.get_count("verbose");
    if verbose >0 {
        let mut builder = env_logger::Builder::from_default_env();
        builder.filter_level(match verbose {
            1 => log::LevelFilter::Warn,
            2 => log::LevelFilter::Debug,
            _ => log::LevelFilter::Trace,
        });
        let _ = builder.try_init();
        log::debug!("CLI Config: {:?}", matches);
    } else {
        let mut builder = env_logger::Builder::from_default_env();
        builder.filter_level(log::LevelFilter::Error);
        let _ = builder.try_init();
    }

    let columns = matches.get_one::<usize>("columns").copied();
    let exclude: Vec<String> = matches.get_many::<String>("exclude").map(|v| v.cloned().collect()).unwrap_or_default();
    let files_flag = matches.get_flag("files");
    let file_input = matches.get_one::<String>("file_input").cloned();
    let hidden = matches.get_flag("hidden");
    let no_ignore = matches.get_flag("no-ignore");
    let no_ignore_parent = matches.get_flag("no-ignore-parent") || no_ignore;
    let no_ignore_dot = matches.get_flag("no-ignore-dot") || no_ignore;
    let no_ignore_vcs = matches.get_flag("no-ignore-vcs") || no_ignore;
    let output = matches.get_one::<String>("output").cloned();
    let streaming = matches.get_one::<String>("streaming").cloned();
    let sort = matches.get_one::<String>("sort").cloned();
    let rsort = matches.get_one::<String>("rsort").cloned();
    let types = matches.get_one::<String>("types").cloned();
    let compact = matches.get_flag("compact");
    let num_format = matches.get_one::<String>("num-format").cloned();
    let input_paths_vec: Vec<PathBuf> = matches.get_many::<String>("input").map(|v| v.map(|s| PathBuf::from(s)).collect()).unwrap_or_default();

    // Handle file_input reading
    if let Some(ref input_path) = file_input {
        let content = if input_path == "stdin" {
            use std::io::Read;
            let mut s = String::new();
            match std::io::stdin().read_to_string(&mut s) {
                Ok(_) => s,
                Err(e) => {
                    eprintln!("Error:\n Failed to parse input file: stdin\n\n{}\n", e);
                    std::process::exit(1);
                }
            }
            s
        } else {
            match std::fs::read_to_string(input_path) {
                Ok(c) => c,
                Err(_) => {
                    eprintln!("Error:\n Failed to parse input file: {}\n\nThis version of tokei was compiled without serialization support for the following formats:\n\n    cbor, json, yaml\n\nYou may want to install any comma separated combination of \"cbor,json,yaml\":\n\n    cargo install tokei --features \"cbor,json,yaml\"\n\nOr use the 'all' feature:\n\n    cargo install tokei --features all\n    \n", input_path);
                    std::process::exit(1);
                }
            }
        };
        match serde_json::from_str::<BTreeMap<String, serde_json::Value>>(&content) {
            Ok(_) => {},
            Err(_) => {
                eprintln!("Error:\n Failed to parse input file: {}\n\nThis version of tokei was compiled without serialization support for the following formats:\n\n    cbor, json, yaml\n\nYou may want to install any comma separated combination of \"cbor,json,yaml\":\n\n    cargo install tokei --features \"cbor,json,yaml\"\n\nOr use the 'all' feature:\n\n    cargo install tokei --features all\n    \n", input_path);
                std::process::exit(1);
            }
        }
    }

    let input_paths: Vec<PathBuf> = if input_paths_vec.is_empty() { vec![PathBuf::from(".")] } else { input_paths_vec };

    for p in &input_paths {
        if !p.exists() {
            eprintln!("Error: '{}' not found.", p.display());
            std::process::exit(1);
        }
    }

    let types_filter: Option<Vec<String>> = types.as_ref().map(|s| s.split(',').map(|t| t.trim().to_ascii_lowercase()).collect());

    // Collect files using ignore crate
    let mut files_via_ignore: Vec<PathBuf> = Vec::new();
    for input in &input_paths {
        if input.is_file() {
            let is_hidden = input.file_name().map(|n| n.to_string_lossy().starts_with('.')).unwrap_or(false);
            if is_hidden && !hidden { continue; }
            let mut excluded = false;
            for pat in &exclude {
                if let Ok(g) = glob::Pattern::new(pat) {
                    let fname = input.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
                    if g.matches(&fname) || g.matches(&input.to_string_lossy().to_string()) {
                        excluded = true; break;
                    }
                }
            }
            if excluded { continue; }
            files_via_ignore.push(input.clone());
        } else if input.is_dir() {
            let mut builder = ignore::WalkBuilder::new(input);
            builder.hidden(!hidden);
            if no_ignore {
                builder.ignore(false);
                builder.git_ignore(false);
                builder.git_global(false);
                builder.git_exclude(false);
                builder.parents(false);
            } else {
                if no_ignore_parent {
                    builder.parents(false);
                }
                if no_ignore_dot {
                    builder.ignore(false);
                }
                if no_ignore_vcs {
                    builder.git_ignore(false);
                    builder.git_global(false);
                    builder.git_exclude(false);
                }
            }
            builder.require_git(false);
            for entry in builder.build() {
                match entry {
                    Ok(e) => {
                        let path = e.path();
                        if path.is_file() {
                            let mut excluded = false;
                            let rel = path.strip_prefix(input).unwrap_or(path);
                            let rel_str = rel.to_string_lossy().to_string();
                            let full_str = path.to_string_lossy().to_string();
                            let file_name = path.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
                            for pat in &exclude {
                                if let Ok(g) = globset::Glob::new(pat) {
                                    if g.compile_matcher().is_match(&file_name) || g.compile_matcher().is_match(rel_str.as_str()) || g.compile_matcher().is_match(full_str.as_str()) {
                                        excluded = true; break;
                                    }
                                }
                                if let Ok(pat_glob) = glob::Pattern::new(pat) {
                                    if pat_glob.matches(&file_name) || pat_glob.matches(&rel_str) || pat_glob.matches(&full_str) {
                                        excluded = true; break;
                                    }
                                    for comp in path.components() {
                                        if let Some(s) = comp.as_os_str().to_str() {
                                            if pat_glob.matches(s) {
                                                excluded = true; break;
                                            }
                                        }
                                    }
                                }
                            }
                            if excluded { continue; }
                            files_via_ignore.push(path.to_path_buf());
                        }
                    },
                    Err(e) => {
                        eprintln!("Error: {}", e);
                    }
                }
            }
        }
    }
    // Handle .tokeignore if needed (manual)
    if !no_ignore && !no_ignore_dot {
        let mut filtered: Vec<PathBuf> = Vec::new();
        for file in files_via_ignore.clone() {
            let mut ignore = false;
            // Find ancestors to check for .tokeignore
            let mut current = file.parent();
            while let Some(dir) = current {
                let tokeignore = dir.join(".tokeignore");
                if tokeignore.exists() {
                    if let Ok(content) = std::fs::read_to_string(&tokeignore) {
                        for line in content.lines() {
                            let pat = line.trim();
                            if pat.is_empty() || pat.starts_with('#') { continue; }
                            if let Ok(glob_pat) = glob::Pattern::new(pat) {
                                let fname = file.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default();
                                let rel_to_dir = file.strip_prefix(dir).map(|p| p.to_string_lossy().to_string()).unwrap_or(file.to_string_lossy().to_string());
                                if glob_pat.matches(&fname) || glob_pat.matches(&rel_to_dir) || glob_pat.matches(&file.to_string_lossy().to_string()) {
                                    ignore = true; break;
                                }
                                for comp in file.components() {
                                    if let Some(s) = comp.as_os_str().to_str() {
                                        if glob_pat.matches(s) {
                                            ignore = true; break;
                                        }
                                    }
                                }
                            }
                            if ignore { break; }
                        }
                    }
                }
                if ignore { break; }
                if no_ignore_parent {
                    // check if next parent is outside input
                    let outside = input_paths.iter().any(|inp| {
                        if file.starts_with(inp) {
                            let dir_str = dir.to_string_lossy();
                            let inp_str = inp.to_string_lossy();
                            !dir_str.starts_with(inp_str.as_ref())
                        } else { false }
                    });
                    // Actually need to detect when dir is outside any input's subtree
                    // Simplify: if dir is not inside any input path, break
                    let inside_any = input_paths.iter().any(|inp| dir.starts_with(inp) || dir == inp);
                    if !inside_any {
                        break;
                    }
                }
                current = dir.parent();
            }
            if !ignore {
                filtered.push(file);
            }
        }
        files_via_ignore = filtered;
    }

    let mut languages_map: BTreeMap<String, Language> = BTreeMap::new();
    let mut total_stats = CodeStats::new();

    for file_path in &files_via_ignore {
        let lang_opt = detect_language(file_path);
        let lang_name = match lang_opt {
            Some(n) => n,
            None => {
                if verbose >=1 {
                    let ext = file_path.extension().and_then(|e| e.to_str()).unwrap_or("");
                    if !ext.is_empty() {
                        log::warn!("Unknown extension: {}", ext);
                    } else {
                        log::warn!("Unknown extension: {}", file_path.file_name().map(|f| f.to_string_lossy().to_string()).unwrap_or_default());
                    }
                }
                continue;
            }
        };
        if let Some(ref filter) = types_filter {
            if !filter.contains(&lang_name.to_ascii_lowercase()) {
                continue;
            }
        }
        let stats = count_lines_for_language(file_path, &lang_name);
        let report = Report { name: file_path.to_string_lossy().to_string(), stats: stats.clone() };
        let entry = languages_map.entry(lang_name.clone()).or_insert_with(|| Language { blanks: 0, code: 0, comments: 0, reports: Vec::new(), children: BTreeMap::new(), inaccurate: false });
        entry.blanks += stats.blanks;
        entry.code += stats.code;
        entry.comments += stats.comments;
        for (blob_lang, blob_stats) in &stats.blobs {
            let blob_report = Report { name: file_path.to_string_lossy().to_string(), stats: blob_stats.clone() };
            entry.children.entry(blob_lang.clone()).or_insert_with(Vec::new).push(blob_report);
        }
        entry.reports.push(report.clone());
        total_stats.blanks += stats.blanks;
        total_stats.code += stats.code;
        total_stats.comments += stats.comments;
        for (_, blob_stats) in &stats.blobs {
            total_stats.blanks += blob_stats.blanks;
            total_stats.code += blob_stats.code;
            total_stats.comments += blob_stats.comments;
        }
    }

    let mut lang_entries: Vec<(String, Language)> = languages_map.into_iter().collect();
    lang_entries.sort_by(|a,b| a.0.cmp(&b.0));
    if let Some(ref sort_key) = sort {
        let key = sort_key.to_ascii_lowercase();
        lang_entries.sort_by(|a,b| {
            let av = match key.as_str() {
                "files" => a.1.reports.len(),
                "lines" => a.1.blanks + a.1.code + a.1.comments,
                "blanks" => a.1.blanks,
                "code" => a.1.code,
                "comments" => a.1.comments,
                _ => 0,
            };
            let bv = match key.as_str() {
                "files" => b.1.reports.len(),
                "lines" => b.1.blanks + b.1.code + b.1.comments,
                "blanks" => b.1.blanks,
                "code" => b.1.code,
                "comments" => b.1.comments,
                _ => 0,
            };
            av.cmp(&bv)
        });
    } else if let Some(ref sort_key) = rsort {
        let key = sort_key.to_ascii_lowercase();
        lang_entries.sort_by(|a,b| {
            let av = match key.as_str() {
                "files" => a.1.reports.len(),
                "lines" => a.1.blanks + a.1.code + a.1.comments,
                "blanks" => a.1.blanks,
                "code" => a.1.code,
                "comments" => a.1.comments,
                _ => 0,
            };
            let bv = match key.as_str() {
