                    let v = serde_json::json!({
                        "name": report.name,
                        "stats": {
                            "blanks": report.stats.blanks,
                            "code": report.stats.code,
                            "comments": report.stats.comments,
                            "blobs": report.stats.blobs
                        }
                    });
                    total_children_correct.entry(name.clone()).or_insert_with(Vec::new).push(v);
                }
            }
            let total_json = serde_json::json!({
                "blanks": total_stats.blanks,
                "code": total_stats.code,
                "comments": total_stats.comments,
                "reports": [],
                "children": total_children_correct,
                "inaccurate": false
            });
            map.insert("Total".to_string(), total_json);
            println!("{}", serde_json::to_string(&map).unwrap());
            return;
        }
    }

    if let Some(ref streaming) = streaming {
        if streaming.to_ascii_lowercase() == "simple" {
            println!("# language                                        path                                          lines         code       comments      blanks   ");
            println!("########## ################################################################################ ############ ############ ############ ############");
            for (lang_name, lang) in &lang_entries {
                for report in &lang.reports {
                    let lines = report.stats.blanks + report.stats.code + report.stats.comments;
