            println!("{}", sep);
        }
    }
    let total_lines = total_stats.blanks + total_stats.code + total_stats.comments;
    let total_files_count: usize = lang_entries.iter().map(|(_,l)| l.reports.len()).sum();
    let total_row = format!(" {:<w$} {:>12} {:>12} {:>12} {:>12} {:>12}",
