fn comment_markers(lang: &str) -> (Option<&'static str>, Option<&'static str>, Option<&'static str>) {
    match lang {
        "Rust" | "C" | "C++" | "C Header" | "C++ Header" | "Java" | "JavaScript" | "TypeScript" | "TSX" | "Go" | "Swift" | "Kotlin" | "Scala" | "C#" | "PHP" | "Dart" | "Haskell" | "Scala" => (Some("//"), Some("/*"), Some("*/")),
        "Python" | "Ruby" | "Shell" | "BASH" | "Perl" | "R" | "Makefile" | "Dockerfile" | "YAML" | "TOML" | "Julia" => (Some("#"), None, None),
        "Markdown" => (None, None, None),
        "HTML" | "XML" => (None, Some("<!--"), Some("-->")),
        "CSS" => (None, Some("/*"), Some("*/")),
        "Plain Text" => (None, None, None),
        _ => (Some("//"), None, None),
    }
}

fn canonical_language(s: &str) -> Option<&'static str> {
    let lower = s.to_ascii_lowercase();
    match lower.as_str() {
        "rust" | "rs" => Some("Rust"),
        "python" | "py" => Some("Python"),
        "javascript" | "js" => Some("JavaScript"),
        "typescript" | "ts" => Some("TypeScript"),
        "c" => Some("C"),
        "c++" | "cpp" | "cxx" => Some("C++"),
        "go" => Some("Go"),
        "java" => Some("Java"),
        "ruby" | "rb" => Some("Ruby"),
        "shell" | "sh" | "bash" => Some("Shell"),
        "json" => Some("JSON"),
        "toml" => Some("TOML"),
        "yaml" | "yml" => Some("YAML"),
        "html" => Some("HTML"),
        "css" => Some("CSS"),
        "markdown" | "md" => Some("Markdown"),
        "dockerfile" => Some("Dockerfile"),
        "makefile" => Some("Makefile"),
        "plain text" | "txt" | "text" => Some("Plain Text"),
        _ => {
            for def in language_definitions() {
                if def.name.to_ascii_lowercase() == lower {
                    return Some(def.name);
                }
            }
            None
        }
    }
}

fn detect_language(path: &Path) -> Option<String> {
    let filename = path.file_name()?.to_string_lossy().to_string();
    let ext_opt = path.extension().and_then(|e| e.to_str()).map(|s| s.to_ascii_lowercase());
    for def in language_definitions() {
        for fname in &def.filenames {
            if filename == *fname || filename.eq_ignore_ascii_case(fname) {
                return Some(def.name.to_string());
            }
        }
    }
    if let Some(ext) = ext_opt {
        for def in language_definitions() {
            for e in &def.extensions {
                if e.eq_ignore_ascii_case(&ext) {
                    return Some(def.name.to_string());
                }
            }
        }
        if ext == "txt" || ext == "text" {
            return Some("Plain Text".to_string());
        }
    } else {
        if filename.eq_ignore_ascii_case("Dockerfile") || filename.eq_ignore_ascii_case("dockerfile") {
            return Some("Dockerfile".to_string());
        }
        if filename.eq_ignore_ascii_case("Makefile") || filename.eq_ignore_ascii_case("makefile") || filename.eq_ignore_ascii_case("GNUmakefile") {
            return Some("Makefile".to_string());
        }
        if filename == "CMakeLists.txt" {
            return Some("CMake".to_string());
        }
    }
    if filename.to_ascii_lowercase().ends_with(".txt") {
        return Some("Plain Text".to_string());
    }
    None
}

fn count_lines_for_language(path: &Path, lang_name: &str) -> CodeStats {
    let content = match std::fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return CodeStats::new(),
    };
    if lang_name == "Markdown" {
        return count_markdown(&content);
    }
    let (line_comment, block_start, block_end) = comment_markers(lang_name);
    let mut stats = CodeStats::new();
    let mut in_block = false;
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            stats.blanks += 1;
            continue;
        }
        if in_block {
            stats.comments += 1;
            if let Some(end) = block_end {
                if trimmed.contains(end) {
                    in_block = false;
                }
            }
            continue;
        }
        if let Some(start) = block_start {
            if trimmed.starts_with(start) {
                stats.comments += 1;
                if let Some(end) = block_end {
                    if !trimmed.contains(end) {
                        in_block = true;
                    } else {
                        // if start and end on same line but not closed? check counts
                        let start_count = trimmed.matches(start).count();
                        let end_count = trimmed.matches(end).count();
                        if start_count > end_count {
                            in_block = true;
                        }
                    }
                } else {
                    in_block = true;
                }
                continue;
            }
        }
        if let Some(lc) = line_comment {
            if trimmed.starts_with(lc) {
                stats.comments += 1;
                continue;
            }
        }
        stats.code += 1;
    }
    stats
}

fn count_markdown(content: &str) -> CodeStats {
    let mut stats = CodeStats::new();
    let mut in_code = false;
    let mut code_lang: Option<String> = None;
    let mut code_lines: Vec<String> = Vec::new();
    let mut blobs: BTreeMap<String, CodeStats> = BTreeMap::new();
    for line in content.lines() {
        let trimmed = line.trim();
        if !in_code && trimmed.starts_with("```") {
            in_code = true;
            let lang = trimmed.trim_start_matches("```").trim().to_string();
            code_lang = if lang.is_empty() { None } else { Some(lang) };
            code_lines.clear();
            continue;
        } else if in_code && trimmed.starts_with("```") {
            in_code = false;
            if let Some(lang) = code_lang.take() {
                if let Some(canonical) = canonical_language(&lang) {
                    let mut blk = CodeStats::new();
                    for cl in &code_lines {
                        let t = cl.trim();
                        if t.is_empty() {
                            blk.blanks += 1;
                        } else {
                            let (lc,_,_) = comment_markers(canonical);
                            if let Some(lc)=lc { if t.starts_with(lc) {blk.comments+=1; continue;} }
                            blk.code+=1;
                        }
                    }
                    blobs.entry(canonical.to_string()).and_modify(|e| {
                        e.blanks += blk.blanks; e.code += blk.code; e.comments += blk.comments;
                    }).or_insert(blk);
                }
            }
            continue;
        }
        if in_code {
            code_lines.push(line.to_string());
        } else {
            if trimmed.is_empty() { stats.blanks += 1; } else { stats.comments += 1; }
        }
    }
    if in_code {
        if let Some(lang) = code_lang {
            if let Some(canonical) = canonical_language(&lang) {
                let mut blk = CodeStats::new();
                for cl in &code_lines {
                    let t = cl.trim();
                    if t.is_empty() { blk.blanks+=1; }
                    else {
                        let (lc,_,_) = comment_markers(canonical);
                        if let Some(lc)=lc { if t.starts_with(lc) {blk.comments+=1; continue;} }
                        blk.code+=1;
                    }
                }
                blobs.entry(canonical.to_string()).and_modify(|e|{
                    e.blanks+=blk.blanks; e.code+=blk.code; e.comments+=blk.comments;
                }).or_insert(blk);
            }
        }
    }
    stats.blobs = blobs;
    stats
}

fn build_cli() -> Command {
    Command::new("tokei")
        .version("14.0.0")
        .about("Count your code, quickly.\nSupport this project on GitHub Sponsors: https://github.com/sponsors/XAMPPRocky")
        .arg(Arg::new("input").help("The path(s) to the file or directory to be counted. (default current directory)").num_args(0..).value_name("input"))
        .arg(Arg::new("columns").short('c').long("columns").help("Sets a strict column width of the output, only available for\nterminal output.").value_name("columns").value_parser(value_parser!(usize)).conflicts_with("output"))
        .arg(Arg::new("exclude").short('e').long("exclude").help("Ignore all files & directories matching the pattern.").value_name("exclude").action(ArgAction::Append))
        .arg(Arg::new("files").short('f').long("files").help("Will print out statistics on individual files.").action(ArgAction::SetTrue))
        .arg(Arg::new("file_input").short('i').long("input").help("Gives statistics from a previous tokei run. Can be given a\nfile path, or \"stdin\" to read from stdin.").value_name("file_input"))
        .arg(Arg::new("hidden").long("hidden").help("Count hidden files.").action(ArgAction::SetTrue))
        .arg(Arg::new("languages").short('l').long("languages").help("Prints out supported languages and their extensions.").action(ArgAction::SetTrue))
        .arg(Arg::new("no-ignore").long("no-ignore").help("Don't respect ignore files (.gitignore, .ignore, etc.). This\nimplies --no-ignore-parent, --no-ignore-dot, and\n--no-ignore-vcs.").action(ArgAction::SetTrue))
        .arg(Arg::new("no-ignore-parent").long("no-ignore-parent").help("Don't respect ignore files (.gitignore, .ignore, etc.) in\nparent directories.").action(ArgAction::SetTrue))
        .arg(Arg::new("no-ignore-dot").long("no-ignore-dot").help("Don't respect .ignore and .tokeignore files, including those\nin parent directories.").action(ArgAction::SetTrue))
        .arg(Arg::new("no-ignore-vcs").long("no-ignore-vcs").help("Don't respect VCS ignore files (.gitignore, .hgignore, etc.)\nincluding those in parent directories.").action(ArgAction::SetTrue))
        .arg(Arg::new("output").short('o').long("output").help("Outputs Tokei in a specific format. Compile with additional\nfeatures for more format support.").value_name("output"))
        .arg(Arg::new("streaming").long("streaming").help("prints the (language, path, lines, blanks, code, comments)\nrecords as simple lines or as Json for batch processing").value_name("streaming").value_parser(["simple","json"]))
        .arg(Arg::new("sort").short('s').long("sort").help("Sort languages based on column").value_name("sort").value_parser(["files","lines","blanks","code","comments"]))
        .arg(Arg::new("rsort").short('r').long("rsort").help("Reverse sort languages based on column").value_name("rsort").value_parser(["files","lines","blanks","code","comments"]))
        .arg(Arg::new("types").short('t').long("types").help("Filters output by language type, separated by a comma. i.e.\n-t=Rust,Markdown").value_name("types"))
        .arg(Arg::new("compact").short('C').long("compact").help("Do not print statistics about embedded languages.").action(ArgAction::SetTrue))
        .arg(Arg::new("num-format").short('n').long("num-format").help("Format of printed numbers, i.e., plain (1234, default),\ncommas (1,234), dots (1.234), or underscores (1_234). Cannot\nbe used with --output.").value_name("num_format_style").value_parser(["commas","dots","plain","underscores"]).conflicts_with("output"))
        .arg(Arg::new("verbose").short('v').long("verbose").help("Set log output level:\n                                        1: to show unknown file extensions,\n                                        2: reserved for future debugging,\n                                        3: enable file level trace. Not\n                                           recommended on multiple files").action(ArgAction::Count))
        .arg(Arg::new("help").short('h').long("help").help("Print help").action(ArgAction::SetTrue))
        .arg(Arg::new("version").short('V').long("version").help("Print version").action(ArgAction::SetTrue))
        .disable_help_flag(true)
        .disable_version_flag(true)
}

